<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Image Preview</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #12192b;
      --panel-2: #182033;
      --text: #e8edf7;
      --muted: #9aa7bd;
      --line: rgba(255, 255, 255, 0.08);
      --accent: #7c8cff;
      --accent-2: #5a6df8;
      --danger: #ff6b7a;
      --shadow: 0 24px 70px rgba(0, 0, 0, 0.45);
      --radius: 20px;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 140, 255, 0.18), transparent 32%),
        linear-gradient(180deg, #080b14 0%, #0d1326 100%);
      color: var(--text);
      padding: 24px;
    }

    .page {
      width: min(920px, 100%);
      display: grid;
      gap: 20px;
    }

    .preview-card {
      background: linear-gradient(180deg, rgba(255,255,255,0.04), rgba(255,255,255,0.02));
      border: 1px solid var(--line);
      border-radius: 28px;
      padding: 18px;
      box-shadow: var(--shadow);
      backdrop-filter: blur(12px);
    }

    .image-shell {
      overflow: hidden;
      border-radius: 22px;
      background: #0f1627;
      border: 1px solid rgba(255,255,255,0.06);
    }

    .image-shell img {
      display: block;
      width: 100%;
      height: min(60vh, 520px);
      object-fit: cover;
    }

    .meta {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 16px;
      margin-top: 16px;
    }

    .details h1 {
      margin: 0 0 4px;
      font-size: clamp(1.2rem, 2vw, 1.8rem);
      letter-spacing: -0.02em;
    }

    .details p {
      margin: 0;
      color: var(--muted);
      font-size: 0.96rem;
    }

    .trigger {
      appearance: none;
      border: 0;
      cursor: pointer;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 10px;
      padding: 0.95rem 1.2rem;
      border-radius: 999px;
      background: linear-gradient(180deg, rgba(255,255,255,0.08), rgba(255,255,255,0.02));
      color: var(--text);
      font-weight: 700;
      transition: transform 160ms ease, background 160ms ease, box-shadow 160ms ease;
      box-shadow: inset 0 0 0 1px rgba(255,255,255,0.08);
    }

    .trigger:hover {
      transform: translateY(-1px);
      background: linear-gradient(180deg, rgba(255,255,255,0.12), rgba(255,255,255,0.04));
    }

    .trigger.danger {
      background: linear-gradient(180deg, rgba(255, 107, 122, 0.22), rgba(255, 107, 122, 0.12));
      box-shadow: inset 0 0 0 1px rgba(255, 107, 122, 0.3);
    }

    .trigger.danger:hover {
      box-shadow: inset 0 0 0 1px rgba(255, 107, 122, 0.45);
    }

    .modal-backdrop {
      position: fixed;
      inset: 0;
      display: grid;
      place-items: center;
      padding: 24px;
      background: rgba(3, 6, 12, 0.72);
      opacity: 0;
      pointer-events: none;
      transition: opacity 180ms ease;
    }

    .modal-backdrop.open {
      opacity: 1;
      pointer-events: auto;
    }

    .modal {
      width: min(100%, 460px);
      border-radius: 24px;
      background: linear-gradient(180deg, rgba(24, 32, 51, 0.98), rgba(15, 21, 36, 0.98));
      border: 1px solid rgba(255,255,255,0.08);
      box-shadow: var(--shadow);
      overflow: hidden;
      transform: translateY(12px) scale(0.98);
      transition: transform 180ms ease;
    }

    .modal-backdrop.open .modal {
      transform: translateY(0) scale(1);
    }

    .modal-header {
      padding: 24px 24px 0;
    }

    .modal-title {
      margin: 0;
      font-size: 1.25rem;
      letter-spacing: -0.02em;
    }

    .modal-body {
      padding: 12px 24px 24px;
      color: var(--muted);
      line-height: 1.55;
    }

    .modal-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      padding: 0 24px 24px;
    }

    .secondary {
      background: rgba(255,255,255,0.05);
      box-shadow: inset 0 0 0 1px rgba(255,255,255,0.08);
    }

    .primary {
      background: linear-gradient(180deg, rgba(255, 107, 122, 0.95), rgba(220, 71, 91, 0.95));
      box-shadow: 0 12px 30px rgba(255, 107, 122, 0.2);
    }

    .status {
      min-height: 1.25em;
      color: #b8f1c8;
      font-size: 0.95rem;
    }
  </style>
</head>
<body>
  <main class="page">
    <section class="preview-card" aria-label="Image preview">
      <div class="image-shell">
        <img
          src="https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1400&q=80"
          alt="A clean workspace with a laptop, notebook, and coffee"
        />
      </div>

      <div class="meta">
        <div class="details">
          <h1>Workspace capture</h1>
          <p>Saved to your image library</p>
        </div>

        <button class="trigger danger" type="button" id="openDeleteDialog">
          Delete image
        </button>
      </div>
    </section>

    <p class="status" id="status" aria-live="polite"></p>
  </main>

  <div class="modal-backdrop" id="deleteModal" aria-hidden="true">
    <div class="modal" role="dialog" aria-modal="true" aria-labelledby="dialogTitle" aria-describedby="dialogDesc">
      <div class="modal-header">
        <h2 class="modal-title" id="dialogTitle">Delete this image?</h2>
      </div>
      <div class="modal-body" id="dialogDesc">
        This will permanently remove the image from your library. You can’t undo this action.
      </div>
      <div class="modal-actions">
        <button class="trigger secondary" type="button" id="cancelDelete">Cancel</button>
        <button class="trigger primary" type="button" id="confirmDelete">Delete</button>
      </div>
    </div>
  </div>

  <script>
    const openButton = document.getElementById('openDeleteDialog');
    const modal = document.getElementById('deleteModal');
    const cancelButton = document.getElementById('cancelDelete');
    const confirmButton = document.getElementById('confirmDelete');
    const status = document.getElementById('status');
    const previewCard = document.querySelector('.preview-card');

    function openModal() {
      modal.classList.add('open');
      modal.setAttribute('aria-hidden', 'false');
      cancelButton.focus();
    }

    function closeModal() {
      modal.classList.remove('open');
      modal.setAttribute('aria-hidden', 'true');
      openButton.focus();
    }

    openButton.addEventListener('click', openModal);
    cancelButton.addEventListener('click', closeModal);

    confirmButton.addEventListener('click', () => {
      previewCard.remove();
      status.textContent = 'Image deleted from your library.';
      closeModal();
    });

    modal.addEventListener('click', (event) => {
      if (event.target === modal) closeModal();
    });

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && modal.classList.contains('open')) {
        closeModal();
      }
    });
  </script>
</body>
</html>
